:root {
  --ink: #170d09;
  --ink-soft: #2b1710;
  --cream: #f4e3c2;
  --cream-dim: #cbb48d;
  --gold: #e9b45e;
  --gold-bright: #ffd587;
  --rust: #a9442d;
  --blood: #8f2119;
  --sage: #87946f;
  --panel: rgba(24, 14, 10, 0.78);
  --line: rgba(233, 180, 94, 0.32);
  --display: 'Rye', Georgia, serif;
  --type: 'Special Elite', 'Courier New', monospace;
  --ui: 'Oswald', 'Arial Narrow', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #130b08;
  color: var(--cream);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}
body { touch-action: none; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.hidden { display: none !important; }

#vignette, #grain, #sun-glare {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 4;
}
#vignette {
  background:
    radial-gradient(ellipse 74% 70% at 50% 45%, transparent 48%, rgba(15, 7, 4, 0.51) 100%),
    linear-gradient(to bottom, rgba(10, 5, 3, 0.35), transparent 17%, transparent 74%, rgba(12, 6, 3, 0.58));
}
#grain {
  opacity: 0.1;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.87' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.9'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  animation: grain-shift 0.42s steps(2) infinite;
}
@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-1.5%, 1%); }
  50% { transform: translate(1%, -1.5%); }
  75% { transform: translate(-1%, -1%); }
  100% { transform: translate(1.5%, 1%); }
}
#sun-glare {
  background: radial-gradient(circle at 77% 27%, rgba(255, 209, 130, 0.14), transparent 19%);
  mix-blend-mode: screen;
}

/* ----------------------------- Loading ----------------------------- */
#loading-screen {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(circle at 50% 46%, #3a2114 0, #180d09 42%, #0d0705 100%);
  transition: opacity 0.7s ease, visibility 0.7s;
}
#loading-screen.gone { opacity: 0; visibility: hidden; }
.loading-mark { width: 44px; height: 44px; color: var(--gold); animation: slow-spin 9s linear infinite; }
.loading-mark svg { width: 100%; height: 100%; fill: currentColor; filter: drop-shadow(0 0 12px rgba(233, 180, 94, 0.45)); }
@keyframes slow-spin { to { transform: rotate(360deg); } }
#loading-screen p {
  margin: 0;
  font-family: var(--type);
  font-size: 10px;
  letter-spacing: 0.38em;
  color: var(--cream-dim);
}
.loading-line { width: 170px; height: 1px; background: rgba(244, 227, 194, 0.16); overflow: hidden; }
.loading-line span { display: block; width: 45%; height: 100%; background: var(--gold); animation: load-sweep 1.2s ease-in-out infinite; }
@keyframes load-sweep { 0% { transform: translateX(-110%); } 100% { transform: translateX(360%); } }

/* ----------------------------- Shared UI ----------------------------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: stretch;
}
.kicker, .micro-label {
  font-family: var(--ui);
  font-weight: 600;
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.26em;
  color: var(--gold);
  text-transform: uppercase;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 500;
  font-size: 10px;
  letter-spacing: 0.3em;
  color: var(--gold);
  text-transform: uppercase;
}
.eyebrow span { display: block; width: 28px; height: 1px; background: linear-gradient(to right, transparent, var(--gold)); }
.eyebrow span:last-child { background: linear-gradient(to left, transparent, var(--gold)); }

.primary-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 28px;
  padding: 17px 25px 17px 30px;
  background: linear-gradient(135deg, #d39c4e 0%, #e8b463 48%, #c47b38 100%);
  color: #231009;
  border: 1px solid #f5cb82;
  box-shadow: 0 0 0 4px rgba(20, 11, 7, 0.7), 0 0 0 5px rgba(233, 180, 94, 0.24), 0 14px 34px rgba(0, 0, 0, 0.36);
  clip-path: polygon(9px 0, 100% 0, calc(100% - 9px) 100%, 0 100%);
  transition: transform 160ms ease, filter 160ms ease;
}
.primary-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,0.25) 50%, transparent 70%);
  transform: translateX(-120%);
  transition: transform 440ms ease;
}
.primary-btn:hover { transform: translateY(-2px) scale(1.01); filter: brightness(1.08); }
.primary-btn:hover::before { transform: translateX(120%); }
.primary-btn:active { transform: translateY(1px) scale(0.99); }
.btn-ink { font-family: var(--ui); font-weight: 600; font-size: 19px; letter-spacing: 0.19em; }
.btn-arrow { font-size: 26px; line-height: 1; font-weight: 400; transform: translateY(-1px); }
.ghost-btn {
  padding: 12px 17px;
  border: 1px solid rgba(244, 227, 194, 0.23);
  color: var(--cream-dim);
  font-size: 10px;
  letter-spacing: 0.2em;
  background: rgba(16, 9, 6, 0.36);
  transition: border-color 150ms, color 150ms, background 150ms;
}
.ghost-btn:hover { border-color: var(--gold); color: var(--gold-bright); background: rgba(233, 180, 94, 0.06); }
kbd {
  display: inline-flex;
  min-width: 28px;
  align-items: center;
  justify-content: center;
  padding: 4px 6px 3px;
  border: 1px solid rgba(244, 227, 194, 0.27);
  border-bottom-color: rgba(244, 227, 194, 0.12);
  background: rgba(244, 227, 194, 0.06);
  color: var(--cream);
  font-family: var(--ui);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.13em;
}

