  position: absolute;
  top: 0; left: 0; right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: calc(18px + env(safe-area-inset-top)) clamp(18px, 3vw, 42px) 0;
}
.hud-brand { display: flex; flex-direction: column; gap: 3px; filter: drop-shadow(0 2px 5px rgba(0,0,0,0.5)); }
