import * as THREE from 'three';

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const rand = (min, max) => min + Math.random() * (max - min);
export const clamp = (v, min, max) => Math.min(max, Math.max(min, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, dt, lambda) => lerp(a, b, 1 - Math.exp(-lambda * dt));

export function canvasTexture(width, height, draw, { repeat = null, srgb = true } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const tex = new THREE.CanvasTexture(canvas);
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  if (repeat) {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(repeat[0], repeat[1]);
  }
  return tex;
}

export function makeSandTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    const rnd = mulberry32(8241);
    const img = ctx.createImageData(w, h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = (y * w + x) * 4;
        const grain = rnd() * 18 - 9;
        const wave = Math.sin(x * 0.06 + Math.sin(y * 0.025) * 2.2) * 4;
        const blotch = Math.sin(x * 0.011 + 1.3) * Math.cos(y * 0.009) * 8;
        img.data[i] = 166 + grain + wave + blotch;
        img.data[i + 1] = 111 + grain * 0.65 + wave * 0.72 + blotch * 0.7;
        img.data[i + 2] = 73 + grain * 0.45 + wave * 0.4 + blotch * 0.45;
        img.data[i + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.globalAlpha = 0.18;
    for (let i = 0; i < 600; i++) {
      const x = rnd() * w;
      const y = rnd() * h;
      const r = 0.5 + rnd() * 2.2;
      ctx.fillStyle = rnd() > 0.5 ? '#5d3925' : '#e0ad72';
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }, { repeat: [26, 26] });
}

export function makeWoodTexture() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const rnd = mulberry32(923);
    ctx.fillStyle = '#6a4029';
    ctx.fillRect(0, 0, w, h);
    const plank = 32;
    for (let y = 0; y < h; y += plank) {
      const tone = 76 + rnd() * 28;
      ctx.fillStyle = `rgb(${tone + 25}, ${tone - 3}, ${tone - 31})`;
      ctx.fillRect(0, y + 1, w, plank - 2);
      ctx.fillStyle = 'rgba(28, 15, 8, 0.58)';
      ctx.fillRect(0, y, w, 1.5);
      ctx.fillStyle = 'rgba(247, 203, 145, 0.06)';
      ctx.fillRect(0, y + 2, w, 1);
      for (let i = 0; i < 14; i++) {
        const gy = y + 4 + rnd() * (plank - 8);
        ctx.strokeStyle = `rgba(38, 20, 11, ${0.07 + rnd() * 0.15})`;
        ctx.lineWidth = 0.5 + rnd();
        ctx.beginPath();
        ctx.moveTo(0, gy);
        ctx.bezierCurveTo(w * 0.3, gy + rnd() * 3 - 1.5, w * 0.7, gy + rnd() * 3 - 1.5, w, gy + rnd() * 2 - 1);
        ctx.stroke();
      }
      for (let i = 0; i < 2; i++) {
        const kx = rnd() * w;
        const ky = y + 8 + rnd() * (plank - 16);
        ctx.strokeStyle = 'rgba(39, 21, 12, 0.3)';
        ctx.beginPath();
        ctx.ellipse(kx, ky, 2 + rnd() * 4, 1 + rnd() * 2, 0, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(21, 12, 7, 0.55)';
      ctx.beginPath();
      ctx.arc(rnd() * w, y + plank / 2, 1.2, 0, Math.PI * 2);
      ctx.fill();
    }
  }, { repeat: [2, 2] });
}

export function makeSignTexture(text, { bg = '#332016', fg = '#e7c281', sub = '', border = true } = {}) {
  return canvasTexture(512, 160, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, bg);
    grad.addColorStop(1, '#1e110b');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    if (border) {
      ctx.strokeStyle = 'rgba(231, 194, 129, 0.55)';
      ctx.lineWidth = 5;
      ctx.strokeRect(10, 10, w - 20, h - 20);
      ctx.strokeStyle = 'rgba(231, 194, 129, 0.2)';
      ctx.lineWidth = 1;
      ctx.strokeRect(19, 19, w - 38, h - 38);
    }
    ctx.fillStyle = fg;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '58px Rye, Georgia, serif';
    ctx.shadowColor = 'rgba(0,0,0,0.55)';
    ctx.shadowBlur = 4;
    ctx.shadowOffsetY = 3;
    ctx.fillText(text, w / 2, sub ? h * 0.42 : h * 0.5);
    if (sub) {
      ctx.shadowBlur = 0;
      ctx.font = '15px Oswald, Arial, sans-serif';
      ctx.fillStyle = 'rgba(231, 194, 129, 0.62)';
      ctx.fillText(sub, w / 2, h * 0.74);
    }
  });
}

export function makePosterTexture() {
  return canvasTexture(256, 340, (ctx, w, h) => {
    ctx.fillStyle = '#d6b57e';
    ctx.fillRect(0, 0, w, h);
    const grad = ctx.createRadialGradient(w / 2, h / 2, 10, w / 2, h / 2, w * 0.75);
    grad.addColorStop(0, 'rgba(120,67,28,0.02)');
    grad.addColorStop(1, 'rgba(57,28,10,0.35)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = '#38200f';
    ctx.fillStyle = '#38200f';
    ctx.textAlign = 'center';
    ctx.font = '58px Rye, Georgia, serif';
    ctx.fillText('WANTED', w / 2, 64);
    ctx.font = '12px Oswald, Arial, sans-serif';
    ctx.letterSpacing = '4px';
    ctx.fillText('DEAD OR ALIVE', w / 2, 84);
    ctx.strokeRect(20, 100, w - 40, 118);
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(82, 175);
    ctx.bezierCurveTo(100, 125, 150, 128, 164, 154);
    ctx.bezierCurveTo(154, 144, 142, 150, 136, 165);
    ctx.lineTo(158, 175);
    ctx.lineTo(126, 181);
    ctx.bezierCurveTo(116, 204, 91, 205, 82, 189);
    ctx.closePath();
    ctx.fill();
    ctx.font = '23px Rye, Georgia, serif';
    ctx.fillText('THE MATRIARCH', w / 2, 246);
    ctx.font = '11px Oswald, Arial, sans-serif';
    ctx.fillText('MURDER · ARSON · STOCK THEFT', w / 2, 264);
    ctx.font = '39px Rye, Georgia, serif';
    ctx.fillText('$5,000', w / 2, 311);
  });
}

export function makeGlowTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.2, 'rgba(255,245,214,0.95)');
    g.addColorStop(0.5, 'rgba(255,180,86,0.38)');
    g.addColorStop(1, 'rgba(255,120,30,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function makeSmokeTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(86,65,54,0.62)');
    g.addColorStop(0.55, 'rgba(60,42,34,0.25)');
    g.addColorStop(1, 'rgba(40,28,22,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function makeSplatTexture() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const rnd = mulberry32(511);
    ctx.clearRect(0, 0, w, h);
    ctx.translate(w / 2, h / 2);
    for (let i = 0; i < 28; i++) {
      const angle = rnd() * Math.PI * 2;
      const dist = rnd() * 70;
      const rx = 16 + rnd() * 38;
      const ry = 10 + rnd() * 26;
      ctx.fillStyle = `rgba(52, 26, 15, ${0.03 + rnd() * 0.08})`;
      ctx.beginPath();
      ctx.ellipse(Math.cos(angle) * dist, Math.sin(angle) * dist, rx, ry, angle, 0, Math.PI * 2);
      ctx.fill();
    }
    for (let i = 0; i < 14; i++) {
      const angle = rnd() * Math.PI * 2;
      const dist = 50 + rnd() * 52;
      ctx.fillStyle = 'rgba(55,28,15,0.22)';
      ctx.beginPath();
      ctx.arc(Math.cos(angle) * dist, Math.sin(angle) * dist, 1 + rnd() * 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

export function makeShadowTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 2, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(20,10,5,0.48)');
    g.addColorStop(0.55, 'rgba(20,10,5,0.25)');
    g.addColorStop(1, 'rgba(20,10,5,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function cylinderBetween(a, b, radius, material, radialSegments = 6) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const length = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, length, radialSegments);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

export function addBox(parent, size, pos, material, rotation = null) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(size[0], size[1], size[2]), material);
  mesh.position.set(pos[0], pos[1], pos[2]);
  if (rotation) mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  parent.add(mesh);
  return mesh;
}

export function addCylinder(parent, rTop, rBottom, height, segments, pos, material, rotation = null) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBottom, height, segments), material);
  mesh.position.set(pos[0], pos[1], pos[2]);
  if (rotation) mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  parent.add(mesh);
  return mesh;
}

export function disposeObject(object) {
  object.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
      else if (!child.material.userData?.shared) child.material.dispose();
    }
  });
  object.removeFromParent();
}

export function srgb(hex) {
  return new THREE.Color(hex);
}

import * as THREE from 'three';
import {
  mulberry32, rand, addBox, addCylinder, makeSandTexture, makeWoodTexture,
  makeSignTexture, makePosterTexture, makeSplatTexture, makeShadowTexture,
  makeGlowTexture, cylinderBetween,
} from './utils.js';

export function createWorld(scene) {
  const rnd = mulberry32(187314);
  const colliders = [];
  const animated = [];
  const dust = [];
  const scorches = [];
  const root = new THREE.Group();
  root.name = 'world';
  scene.add(root);

  const sandTex = makeSandTexture();
  const woodTex = makeWoodTexture();
  const posterTex = makePosterTexture();
  const splatTex = makeSplatTexture();
  const shadowTex = makeShadowTexture();
  const glowTex = makeGlowTexture();

  const mat = {
    wood: new THREE.MeshStandardMaterial({ map: woodTex, color: 0xb88662, roughness: 0.94, metalness: 0 }),
    darkWood: new THREE.MeshStandardMaterial({ map: woodTex, color: 0x5d3b2a, roughness: 0.94 }),
    trim: new THREE.MeshStandardMaterial({ map: woodTex, color: 0x3f281c, roughness: 0.9 }),
    roof: new THREE.MeshStandardMaterial({ color: 0x4f3023, roughness: 0.95 }),
    roofRed: new THREE.MeshStandardMaterial({ color: 0x713528, roughness: 0.95 }),
    plaster: new THREE.MeshStandardMaterial({ color: 0xb99a6f, roughness: 1 }),
    stone: new THREE.MeshStandardMaterial({ color: 0x876144, roughness: 1, flatShading: true }),
    metal: new THREE.MeshStandardMaterial({ color: 0x4b4238, roughness: 0.5, metalness: 0.7 }),
    glass: new THREE.MeshStandardMaterial({ color: 0x2b1c14, roughness: 0.25, metalness: 0.4 }),
    window: new THREE.MeshStandardMaterial({ color: 0xffc066, emissive: 0xff8628, emissiveIntensity: 1.35, roughness: 0.6 }),
    lantern: new THREE.MeshStandardMaterial({ color: 0xffd18a, emissive: 0xff8e2b, emissiveIntensity: 2.2 }),
    cactus: new THREE.MeshStandardMaterial({ color: 0x526042, roughness: 0.92, flatShading: true }),
    cactusDark: new THREE.MeshStandardMaterial({ color: 0x3a4631, roughness: 0.95, flatShading: true }),
    rock: new THREE.MeshStandardMaterial({ color: 0x8a5c43, roughness: 1, flatShading: true }),
    mesa: new THREE.MeshStandardMaterial({ color: 0x8f4b39, roughness: 1, flatShading: true }),
    mesaTop: new THREE.MeshStandardMaterial({ color: 0xab6143, roughness: 1, flatShading: true }),
    mesaDark: new THREE.MeshStandardMaterial({ color: 0x6b372e, roughness: 1, flatShading: true }),
    black: new THREE.MeshStandardMaterial({ color: 0x201510, roughness: 0.9 }),
    hide: new THREE.MeshStandardMaterial({ color: 0x9a6a44, roughness: 0.9 }),
  };

  // ---------------------------------------------------------------- Sky
  const sunDir = new THREE.Vector3(-0.56, 0.22, -0.8).normalize();
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(300, 36, 20),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        topColor: { value: new THREE.Color('#152b3f') },
        midColor: { value: new THREE.Color('#7f5261') },
        horizonColor: { value: new THREE.Color('#e9a063') },
        lowColor: { value: new THREE.Color('#7d4634') },
        sunColor: { value: new THREE.Color('#ffd79a') },
        sunDir: { value: sunDir },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vec4 world = modelMatrix * vec4(position, 1.0);
          vDir = normalize(world.xyz);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 topColor, midColor, horizonColor, lowColor, sunColor, sunDir;
        void main() {
          float h = vDir.y;
          vec3 col = mix(horizonColor, midColor, smoothstep(0.01, 0.30, h));
          col = mix(col, topColor, smoothstep(0.27, 0.82, h));
          col = mix(lowColor, col, smoothstep(-0.10, 0.015, h));
          float sun = max(dot(vDir, sunDir), 0.0);
          col += sunColor * pow(sun, 900.0) * 2.5;
          col += sunColor * pow(sun, 14.0) * 0.19;
          col += horizonColor * pow(sun, 3.0) * 0.09;
          float band = sin(h * 45.0 + sin(vDir.x * 8.0)) * 0.5 + 0.5;
          col += horizonColor * band * 0.012 * smoothstep(0.35, 0.0, h);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    }),
  );
  sky.frustumCulled = false;
  root.add(sky);

  const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex,
    color: 0xffdfab,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    fog: false,
  }));
  sunSprite.position.copy(sunDir).multiplyScalar(220);
  sunSprite.scale.set(53, 53, 1);
  root.add(sunSprite);

  // Wispy sunset clouds
  const cloudMat = new THREE.MeshBasicMaterial({
    color: 0xe0a17d, transparent: true, opacity: 0.16, depthWrite: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide, fog: false,
  });
  for (let i = 0; i < 9; i++) {
    const cloud = new THREE.Mesh(new THREE.PlaneGeometry(rand(55, 125), rand(4, 9)), cloudMat);
    const a = rand(0, Math.PI * 2);
    const r = rand(150, 220);
    cloud.position.set(Math.cos(a) * r, rand(38, 72), Math.sin(a) * r);
    cloud.lookAt(0, cloud.position.y, 0);
    cloud.rotation.z += rand(-0.12, 0.12);
    root.add(cloud);
  }

  // ---------------------------------------------------------------- Lighting
  scene.fog = new THREE.FogExp2(0xc08562, 0.0057);
  scene.background = new THREE.Color('#ae7558');
  const hemi = new THREE.HemisphereLight(0xffd7a6, 0x5d3b36, 2.1);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xffbc7d, 3.7);
  sun.position.set(-54, 48, -63);
  sun.target.position.set(0, 0, 4);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 180;
  sun.shadow.camera.left = -72;
  sun.shadow.camera.right = 72;
  sun.shadow.camera.top = 72;
  sun.shadow.camera.bottom = -72;
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.03;
  scene.add(sun, sun.target);
  const bounce = new THREE.DirectionalLight(0x5c7a95, 0.5);
  bounce.position.set(35, 22, 40);
  scene.add(bounce);

  // ---------------------------------------------------------------- Ground
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(420, 420, 1, 1),
    new THREE.MeshStandardMaterial({ map: sandTex, color: 0xe7ad7d, roughness: 1, metalness: 0 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  root.add(ground);

  const roadMat = new THREE.MeshStandardMaterial({ color: 0x7d4d37, roughness: 1, transparent: true, opacity: 0.55 });
  const road = new THREE.Mesh(new THREE.PlaneGeometry(10.5, 158), roadMat);
  road.rotation.x = -Math.PI / 2;
  road.position.set(0, 0.015, -1);
  root.add(road);
  for (const side of [-1, 1]) {
    const rut = new THREE.Mesh(
      new THREE.PlaneGeometry(0.3, 158),
      new THREE.MeshBasicMaterial({ color: 0x583426, transparent: true, opacity: 0.26 }),
    );
    rut.rotation.x = -Math.PI / 2;
    rut.position.set(side * 2.3, 0.025, -1);
    root.add(rut);
  }

  for (let i = 0; i < 34; i++) {
    const splat = new THREE.Mesh(
      new THREE.PlaneGeometry(rand(4, 13), rand(3, 10)),
      new THREE.MeshBasicMaterial({ map: splatTex, transparent: true, opacity: rand(0.3, 0.7), depthWrite: false }),
    );
    splat.rotation.x = -Math.PI / 2;
    splat.rotation.z = rand(0, Math.PI * 2);
    splat.position.set(rand(-65, 65), 0.03, rand(-70, 65));
    root.add(splat);
  }

  // ---------------------------------------------------------------- Props
  function addCollider(x, z, hx, hz, tag = '') {
    colliders.push({ minX: x - hx, maxX: x + hx, minZ: z - hz, maxZ: z + hz, tag });
  }

  function makeLantern(x, y, z, parent) {
    const body = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.15, 0.36, 6), mat.lantern);
    body.position.set(x, y, z);
    parent.add(body);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xffa452, transparent: true, opacity: 0.75,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.scale.set(1.4, 1.4, 1);
    glow.position.set(x, y, z);
    parent.add(glow);
    animated.push({ type: 'lantern', mesh: body, glow, offset: Math.random() * 10, base: 1.8 });
    return body;
  }

  function makeBuilding(cfg) {
    const {
      x, z, w = 8, d = 11, h = 4.4, side = -1, name = 'SALOON', tone = 0,
      roofColor = 'roof', falseFront = true, twoStory = false, height = null,
    } = cfg;
    const bh = height ?? h;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
    root.add(g);

    const baseMat = tone > 1 ? mat.plaster : mat.wood;
    addBox(g, [w, bh, d], [0, bh / 2, 0], baseMat).castShadow = true;
    addBox(g, [w + 0.22, 0.18, d + 0.22], [0, 0.09, 0], mat.trim);

    // corner beams and siding bands
    for (const sx of [-1, 1]) {
      addBox(g, [0.17, bh, 0.17], [sx * (w / 2 - 0.05), bh / 2, d / 2 + 0.02], mat.trim);
    }
    addBox(g, [w + 0.15, 0.13, 0.13], [0, bh - 0.5, d / 2 + 0.03], mat.trim);

    if (falseFront) {
      addBox(g, [w + 0.45, bh + 1.35, 0.32], [0, (bh + 1.35) / 2, d / 2 + 0.18], mat[roofColor]);
      addBox(g, [w + 0.7, 0.2, 0.5], [0, bh + 1.42, d / 2 + 0.18], mat.trim);
      if (twoStory) addBox(g, [w + 0.6, 0.18, 0.5], [0, bh - 1.05, d / 2 + 0.2], mat.trim);
    } else {
      const slope = 0.34;
      const half = w * 0.55;
      for (const sx of [-1, 1]) {
        const pane = addBox(g, [half, 0.18, d + 0.8], [sx * w * 0.245, bh + 0.36, 0], mat[roofColor], [0, 0, sx * slope]);
        pane.castShadow = true;
      }
      addBox(g, [0.22, 0.22, d + 1], [0, bh + 1.03, 0], mat.trim);
    }

    // porch
    addBox(g, [w + 1.15, 0.17, 2.9], [0, 0.12, d / 2 + 1.38], mat.trim);
    const porchRoof = addBox(g, [w + 1.6, 0.15, 3.15], [0, 3.22, d / 2 + 1.45], mat.roof);
    porchRoof.castShadow = true;
