    mesh.position.copy(position);
    mesh.position.y = 0.04;
    root.add(mesh);
    scorches.push({ mesh, life: 18 });
    if (scorches.length > 22) {
      const old = scorches.shift();
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
      old.mesh.removeFromParent();
    }
    return mesh;
